.oc-showcase{padding-top:80px;padding-bottom:90px}.oc-showcase .section-heading{margin-bottom:32px}.oc-device-scene{position:relative;min-height:610px;margin:0;border-radius:28px;background:radial-gradient(ellipse at 50% 75%,#dfeaca 0,transparent 60%),linear-gradient(135deg,#f1f5eb,#f8faf7);overflow:hidden}.oc-device{margin:0;position:absolute}.oc-device img{width:100%;height:100%;object-fit:cover;object-position:top;display:block}.oc-device figcaption{font-size:14px;font-weight:650;text-align:center;margin-top:22px;color:#294b3b}.oc-laptop{width:61%;left:4%;top:19%;z-index:1}.oc-laptop-lid{padding:12px 12px 16px;border:2px solid #474a47;background:#171e1b;border-radius:18px 18px 8px 8px;box-shadow:0 24px 35px #203e2822;aspect-ratio:1.44}.oc-laptop-lid img{border-radius:6px}.oc-laptop-base{width:112%;height:18px;margin-left:-6%;background:linear-gradient(#d9ddd9,#a7afa8);border-radius:2px 2px 60% 60%;box-shadow:0 9px 9px #18362c20}.oc-laptop-base:before{content:'';display:block;background:#9ca49e;width:17%;height:5px;margin:auto;border-radius:0 0 8px 8px}.oc-tablet{width:28%;right:7%;top:8%;z-index:2}.oc-tablet-body{background:#18201a;padding:13px;border-radius:23px;border:2px solid #4e574e;box-shadow:0 24px 35px #19392433;aspect-ratio:820/1180}.oc-tablet-body img{border-radius:10px}.oc-phone{width:15.5%;right:1.5%;top:40%;z-index:3}.oc-phone-body{position:relative;padding:7px;background:#172019;border:2px solid #606760;border-radius:24px;box-shadow:0 20px 30px #173d3233;aspect-ratio:390/844}.oc-phone-body img{border-radius:16px}.oc-phone-body:before{content:'';position:absolute;width:22%;height:5px;border-radius:6px;background:#172019;top:8px;left:39%}.oc-media-note{font-size:13px;line-height:1.6;color:#607065;margin-top:18px;max-width:850px}.oc-device-benefits{display:grid;grid-template-columns:repeat(3,1fr);gap:40px;margin-top:44px}.oc-device-benefits h3{font-size:20px;line-height:1.3;margin-bottom:12px;letter-spacing:-.03em}.oc-device-benefits p{font-size:16px;color:var(--muted)}.oc-video-section{padding:80px 0;background:#edf3e5}.oc-video-layout{display:grid;grid-template-columns:.8fr 1.3fr;align-items:center;gap:60px}.oc-video-copy h2{font-size:clamp(32px,3.5vw,46px);line-height:1.15;margin:18px 0}.oc-video-copy>p:not(.eyebrow):not(.oc-media-note){font-size:16px;color:var(--muted);margin-bottom:26px}.oc-video-player{margin:0}.oc-video-player video{display:block;width:100%;aspect-ratio:16/9;background:#163d32;border-radius:14px;box-shadow:0 22px 55px #173d3222}.oc-video-player figcaption{font-size:14px;color:var(--muted);margin-top:16px}.oc-video-player video:focus-visible{outline:3px solid #658135;outline-offset:6px}
@media(max-width:1000px){.site-navigation{gap:14px;font-size:13px}.oc-device-scene{min-height:490px}.oc-video-layout{grid-template-columns:1fr;gap:32px}.oc-video-copy{max-width:650px}.oc-device-benefits{gap:24px}}
@media(max-width:640px){.oc-showcase{padding-top:42px;padding-bottom:45px}.oc-device-scene{min-height:500px;border-radius:18px}.oc-laptop{width:87%;left:6%;top:7%}.oc-laptop-lid{padding:6px;border-radius:9px}.oc-laptop-base{height:9px}.oc-tablet{width:46%;right:40%;top:44%}.oc-tablet-body{padding:6px;border-radius:14px}.oc-tablet-body img{border-radius:7px}.oc-phone{width:26%;right:9%;top:48%}.oc-phone-body{padding:4px;border-radius:16px}.oc-phone-body img{border-radius:10px}.oc-device figcaption{font-size:12px;margin-top:12px}.oc-device-benefits{grid-template-columns:1fr;gap:24px;margin-top:32px}.oc-device-benefits h3{font-size:20px}.oc-video-section{padding:45px 0}.oc-video-copy h2{font-size:34px}.oc-showcase .section-heading h2{font-size:34px}}
@media(max-width:375px){.oc-device-scene{min-height:440px}}
@media(min-width:1001px){.oc-device-scene{min-height:660px}.oc-laptop{top:14%}.oc-phone{top:34%;width:14.5%}}
.oc-tablet-body{aspect-ratio:820/1059}
.oc-device figcaption{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
